// Shared data for the home page's demos: the theme packs (every Lens pack plus the community
// collection), generated by tools/site/lib/packs.mjs from the real pack registry.
const SITE = new URL("../", import.meta.url);
let packsP;
export const getPacks = () => (packsP ??= fetch(new URL("data/packs.json", SITE)).then((r) => r.json()));
